protected RealMatrix computeCovarianceMatrix(RealMatrix matrix, boolean biasCorrected)
    throws MathIllegalArgumentException {
    checkSufficientData(matrix);

    final int nCols = matrix.getColumnDimension();
    final RealMatrix covariance = matrix.createMatrix(nCols, nCols);

    for (int i = 0; i < nCols; i++) {
        final double[] x = matrix.getColumn(i);
        for (int j = i; j < nCols; j++) {
            final double value = covariance(x, matrix.getColumn(j), biasCorrected);
            covariance.setEntry(i, j, value);
            covariance.setEntry(j, i, value);
        }
    }

    return covariance;
}
